1	package main
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"os"
9		"path/filepath"
10		"sort"
11		"time"
12	)
13	
14	// 包裹状态。
15	const (
16		// statusInStation 表示包裹当前在某站点（已收件、已完成交接或回执失败回到出发站）。
17		statusInStation = "在站"
18		// statusDelivering 表示包裹已随某个配送批次出站，正在配送中。
19		statusDelivering = "配送中"
20		// statusSigned 表示包裹已签收（回执结果为签收）。
21		statusSigned = "已签收"
22		// statusFrozen 表示在站包裹因异常被冻结：站点不变，禁止交接、配送出站与整批退回。
23		statusFrozen = "异常冻结"
24	)
25	
26	// 回执结果。
27	const (
28		resultSigned = "签收"
29		resultFailed = "失败"
30	)
31	
32	// Event 是包裹轨迹中的一条记录，按提交顺序追加。
33	type Event struct {
34		Op         string    `json:"op"`                   // 收件 | 交接 | 退回 | 出站 | 回执 | 冻结 | 解除冻结
35		Station    string    `json:"station"`              // 与该操作有关的站点（退回时为退回目的站，即原交接源站；冻结/解除冻结为包裹所在站点）
36		Time       time.Time `json:"time"`                 // 发生时间
37		Request    string    `json:"request,omitempty"`    // 交接/退回/回执请求号（收件、出站记录为空）
38		From       string    `json:"from,omitempty"`       // 退回源站（原交接目的站，仅退回记录有）
39		Reason     string    `json:"reason,omitempty"`     // 退回原因（仅退回记录有）、回执失败原因（仅失败回执有）或冻结原因（仅冻结记录有）
40		RefRequest string    `json:"refRequest,omitempty"` // 被退回的原交接请求号（仅退回记录有）
41		Batch      string    `json:"batch,omitempty"`      // 配送批次号（仅出站、回执记录有）
42		Courier    string    `json:"courier,omitempty"`    // 配送员（仅出站记录有）
43		Result     string    `json:"result,omitempty"`     // 回执结果：签收 | 失败（仅回执记录有）
44		// Incident 为冻结/解除冻结记录的异常单号；解除冻结时另外用 Request 存解除请求号、Note 存处理说明。
45		Incident string `json:"incident,omitempty"`
46		Note     string `json:"note,omitempty"`
47	}
48	
49	// Parcel 是一件包裹的台账信息。
50	type Parcel struct {
51		ID         string    `json:"id"`
52		Station    string    `json:"station"`    // 当前归属站点
53		Status     string    `json:"status"`     // 当前状态
54		Registered time.Time `json:"registered"` // 收件时间
55		Trail      []Event   `json:"trail"`      // 完整轨迹，按提交顺序排列
56	}
57	
58	// HandoffResult 记录一次成功交接，用于请求号去重与结果重放。
59	type HandoffResult struct {
60		Request    string    `json:"request"`
61		From       string    `json:"from"`
62		To         string    `json:"to"`
63		Parcels    []string  `json:"parcels"` // 按首次提交时给出的顺序保存
64		Time       time.Time `json:"time"`
65		ReturnedBy string    `json:"returnedBy,omitempty"` // 已成功退回该交接的退回请求号（未退回为空）
66	}
67	
68	// ReturnResult 记录一次成功的整批退回，用于退回请求号去重与结果重放。
69	type ReturnResult struct {
70		Request string    `json:"request"` // 退回请求号
71		Handoff string    `json:"handoff"` // 被退回的原交接请求号
72		From    string    `json:"from"`    // 退回源站（原交接目的站）
73		To      string    `json:"to"`      // 退回目的站（原交接源站）
74		Reason  string    `json:"reason"`
75		Parcels []string  `json:"parcels"` // 原交接批次，按原交接保存的顺序
76		Time    time.Time `json:"time"`
77	}
78	
79	// ReceiptEntry 是批次内一件包裹的回执记录。
80	type ReceiptEntry struct {
81		Request string    `json:"request"`          // 回执请求号
82		Result  string    `json:"result"`           // 签收 | 失败
83		Reason  string    `json:"reason,omitempty"` // 失败原因（仅失败回执有）
84		Time    time.Time `json:"time"`
85	}
86	
87	// BatchResult 记录一次成功的配送批次出站，用于批次号去重、结果重放与批次查询。
88	// 成员按首次提交时给出的顺序保存，保存后不可修改；批次完成后批次号也不能复用。
89	type BatchResult struct {
90		Batch    string                   `json:"batch"`
91		Station  string                   `json:"station"`  // 出发站
92		Courier  string                   `json:"courier"`  // 配送员
93		Parcels  []string                 `json:"parcels"`  // 批次成员，按首次提交顺序
94		Time     time.Time                `json:"time"`     // 出站时间
95		Receipts map[string]*ReceiptEntry `json:"receipts"` // 逐件回执，按包裹编号索引（未回执的包裹不在其中）
96	}
97	
98	// Done 报告批次是否已完成（全部成员均已回执）。
99	func (b *BatchResult) Done() bool { return len(b.Receipts) == len(b.Parcels) }
100	
101	// ReceiptResult 记录一次成功的逐件回执，用于回执请求号去重与结果重放。
102	type ReceiptResult struct {
103		Request string    `json:"request"` // 回执请求号
104		Batch   string    `json:"batch"`   // 所属配送批次号
105		Parcel  string    `json:"parcel"`  // 包裹编号
106		Result  string    `json:"result"`  // 签收 | 失败
107		Reason  string    `json:"reason,omitempty"`
108		Time    time.Time `json:"time"`
109	}
110	
111	// FreezeResult 记录一次成功的异常冻结，用于异常单号去重与结果重放。
112	// 异常单号标识一次异常，解除后也不能复用；失败的首次冻结不占用异常单号。
113	type FreezeResult struct {
114		Incident string    `json:"incident"` // 异常单号
115		Parcel   string    `json:"parcel"`   // 被冻结的包裹编号
116		Station  string    `json:"station"`  // 冻结时包裹所在站点（冻结与解除期间均不变）
117		Reason   string    `json:"reason"`   // 清理后的冻结原因
118		Time     time.Time `json:"time"`     // 冻结时间
119		// ReleasedBy 为解除该异常单的解除请求号（未解除为空）；解除后异常单永久保留、不得复用。
120		ReleasedBy string `json:"releasedBy,omitempty"`
121	}
122	
123	// UnfreezeResult 记录一次成功的解除冻结，用于解除请求号去重与结果重放。
124	// 解除请求号独立去重，可与异常单号、包裹号及其他业务编号同名；失败的首次解除不占用请求号。
125	type UnfreezeResult struct {
126		Request  string    `json:"request"`  // 解除请求号
127		Incident string    `json:"incident"` // 被解除的异常单号
128		Parcel   string    `json:"parcel"`   // 对应包裹编号
129		Note     string    `json:"note"`     // 清理后的处理说明
130		Time     time.Time `json:"time"`     // 解除时间
131	}
132	
133	// ledgerFile 是本地数据文件的磁盘结构。
134	type ledgerFile struct {
135		Version   int                        `json:"version"`
136		Parcels   map[string]*Parcel         `json:"parcels"`
137		Handoffs  map[string]*HandoffResult  `json:"handoffs"`
138		Returns   map[string]*ReturnResult   `json:"returns"`
139		Batches   map[string]*BatchResult    `json:"batches"`
140		Receipts  map[string]*ReceiptResult  `json:"receipts"`
141		Freezes   map[string]*FreezeResult   `json:"freezes"`   // 以异常单号为键（含已解除的异常单，永久保留）
142		Unfreezes map[string]*UnfreezeResult `json:"unfreezes"` // 以解除请求号为键
143	}
144	
145	// Store 是一个数据文件对应的包裹站点交接台账。
146	type Store struct {
147		path string
148		data ledgerFile
149	}
150	
151	var (
152		// ErrCorrupt 表示数据文件已存在但内容损坏，不得当作空库继续读写。
153		ErrCorrupt = errors.New("数据文件已损坏")
154		// ErrNotFound 表示包裹编号在台账中不存在。
155		ErrNotFound = errors.New("包裹不存在")
156	)
157	
158	// Open 打开（或在文件不存在时建立）一个本地台账。
159	// 文件不存在时仅初始化内存结构，真正建文件发生在首次成功保存时。
160	func Open(path string) (*Store, error) {
161		s := &Store{path: path}
162		raw, err := os.ReadFile(path)
163		if err != nil {
164			if os.IsNotExist(err) {
165				s.data = ledgerFile{Version: 1, Parcels: map[string]*Parcel{}, Handoffs: map[string]*HandoffResult{},
166					Returns: map[string]*ReturnResult{}, Batches: map[string]*BatchResult{}, Receipts: map[string]*ReceiptResult{},
167					Freezes: map[string]*FreezeResult{}, Unfreezes: map[string]*UnfreezeResult{}}
168				return s, nil
169			}
170			return nil, fmt.Errorf("读取数据文件失败: %w", err)
171		}
172		if len(bytes.TrimSpace(raw)) == 0 {
173			return nil, fmt.Errorf("%w: 文件为空", ErrCorrupt)
174		}
175		if err := json.Unmarshal(raw, &s.data); err != nil {
176			return nil, fmt.Errorf("%w: %v", ErrCorrupt, err)
177		}
178		if s.data.Version != 1 || s.data.Parcels == nil || s.data.Handoffs == nil {
179			return nil, fmt.Errorf("%w: 缺少必要字段或版本不受支持", ErrCorrupt)
180		}
181		// 早期版本的数据文件没有 returns/batches/receipts/freeze 相关字段：按空表处理，无需手工修改。
182		if s.data.Returns == nil {
183			s.data.Returns = map[string]*ReturnResult{}
184		}
185		if s.data.Batches == nil {
186			s.data.Batches = map[string]*BatchResult{}
187		}
188		if s.data.Receipts == nil {
189			s.data.Receipts = map[string]*ReceiptResult{}
190		}
191		if s.data.Freezes == nil {
192			s.data.Freezes = map[string]*FreezeResult{}
193		}
194		if s.data.Unfreezes == nil {
195			s.data.Unfreezes = map[string]*UnfreezeResult{}
196		}
197		for _, b := range s.data.Batches {
198			if b != nil && b.Receipts == nil {
199				b.Receipts = map[string]*ReceiptEntry{}
200			}
201		}
202		if err := s.data.validate(); err != nil {
203			return nil, err
204		}
205		return s, nil
206	}
207	
208	// validate 校验载入内容内部自洽，防止损坏数据被当作有效台账继续使用。
209	func (l *ledgerFile) validate() error {
210		for id, p := range l.Parcels {
211			if p == nil || id != p.ID || p.Station == "" || p.Status == "" || len(p.Trail) == 0 {
212				return fmt.Errorf("%w: 包裹 %q 记录不完整", ErrCorrupt, id)
213			}
214			switch p.Status {
215			case statusInStation, statusDelivering, statusSigned, statusFrozen:
216			default:
217				return fmt.Errorf("%w: 包裹 %q 的状态 %q 不受支持", ErrCorrupt, id, p.Status)
218			}
219			for i, e := range p.Trail {
220				if e.Op == "" || e.Station == "" || e.Time.IsZero() {
221					return fmt.Errorf("%w: 包裹 %q 第 %d 条轨迹缺少操作、站点或发生时间", ErrCorrupt, id, i+1)
222				}
223				if e.Op == "退回" {
224					if e.Request == "" || e.Reason == "" || e.From == "" {
225						return fmt.Errorf("%w: 包裹 %q 第 %d 条退回轨迹缺少退回请求号、源站或原因", ErrCorrupt, id, i+1)
226					}
227					if _, ok := l.Handoffs[e.RefRequest]; !ok {
228						return fmt.Errorf("%w: 包裹 %q 第 %d 条退回轨迹引用了不存在的原交接 %q", ErrCorrupt, id, i+1, e.RefRequest)
229					}
230				}
231				if e.Op == "出站" {
232					if e.Batch == "" || e.Courier == "" {
233						return fmt.Errorf("%w: 包裹 %q 第 %d 条出站轨迹缺少批次号或配送员", ErrCorrupt, id, i+1)
234					}
235					if _, ok := l.Batches[e.Batch]; !ok {
236						return fmt.Errorf("%w: 包裹 %q 第 %d 条出站轨迹引用了不存在的批次 %q", ErrCorrupt, id, i+1, e.Batch)
237					}
238				}
239				if e.Op == "回执" {
240					if e.Batch == "" || e.Request == "" || (e.Result != resultSigned && e.Result != resultFailed) {
241						return fmt.Errorf("%w: 包裹 %q 第 %d 条回执轨迹缺少批次号、请求号或结果无效", ErrCorrupt, id, i+1)
242					}
243					if e.Result == resultFailed && e.Reason == "" {
244						return fmt.Errorf("%w: 包裹 %q 第 %d 条失败回执轨迹缺少原因", ErrCorrupt, id, i+1)
245					}
246					if _, ok := l.Batches[e.Batch]; !ok {
247						return fmt.Errorf("%w: 包裹 %q 第 %d 条回执轨迹引用了不存在的批次 %q", ErrCorrupt, id, i+1, e.Batch)
248					}
249				}
250				if e.Op == "冻结" {
251					if e.Incident == "" || e.Reason == "" {
252						return fmt.Errorf("%w: 包裹 %q 第 %d 条冻结轨迹缺少异常单号或原因", ErrCorrupt, id, i+1)
253					}
254					f, ok := l.Freezes[e.Incident]
255					if !ok {
256						return fmt.Errorf("%w: 包裹 %q 第 %d 条冻结轨迹引用了不存在的异常单 %q", ErrCorrupt, id, i+1, e.Incident)
257					}
258					if f.Parcel != id || f.Reason != e.Reason || f.Station != e.Station || !f.Time.Equal(e.Time) {
259						return fmt.Errorf("%w: 包裹 %q 第 %d 条冻结轨迹与异常单 %q 记录不一致", ErrCorrupt, id, i+1, e.Incident)
260					}
261				}
262				if e.Op == "解除冻结" {
263					if e.Incident == "" || e.Request == "" || e.Note == "" {
264						return fmt.Errorf("%w: 包裹 %q 第 %d 条解除冻结轨迹缺少异常单号、解除请求号或处理说明", ErrCorrupt, id, i+1)
265					}
266					f, ok := l.Freezes[e.Incident]
267					if !ok {
268						return fmt.Errorf("%w: 包裹 %q 第 %d 条解除冻结轨迹引用了不存在的异常单 %q", ErrCorrupt, id, i+1, e.Incident)
269					}
270					if f.Parcel != id || f.Station != e.Station || f.ReleasedBy != e.Request {
271						return fmt.Errorf("%w: 包裹 %q 第 %d 条解除冻结轨迹与异常单 %q 不匹配", ErrCorrupt, id, i+1, e.Incident)
272					}
273					u, ok := l.Unfreezes[e.Request]
274					if !ok || u.Incident != e.Incident || u.Parcel != id || u.Note != e.Note || !u.Time.Equal(e.Time) {
275						return fmt.Errorf("%w: 包裹 %q 第 %d 条解除冻结轨迹与解除请求 %q 记录不一致", ErrCorrupt, id, i+1, e.Request)
276					}
277				}
278			}
279		}
280		for req, h := range l.Handoffs {
281			if h == nil || req != h.Request || h.From == "" || h.To == "" || len(h.Parcels) == 0 {
282				return fmt.Errorf("%w: 请求号 %q 的交接结果不完整", ErrCorrupt, req)
283			}
284			for _, id := range h.Parcels {
285				if _, ok := l.Parcels[id]; !ok {
286					return fmt.Errorf("%w: 请求号 %q 引用了不存在的包裹 %q", ErrCorrupt, req, id)
287				}
288			}
289			if h.ReturnedBy != "" {
290				r, ok := l.Returns[h.ReturnedBy]
291				if !ok || r.Handoff != req {
292					return fmt.Errorf("%w: 交接 %q 标记的退回请求号 %q 无法对应", ErrCorrupt, req, h.ReturnedBy)
293				}
294			}
295		}
296		for req, r := range l.Returns {
297			if r == nil || req != r.Request || r.Handoff == "" || r.From == "" || r.To == "" ||
298				r.Reason == "" || len(r.Parcels) == 0 || r.Time.IsZero() {
299				return fmt.Errorf("%w: 退回请求号 %q 的退回结果不完整", ErrCorrupt, req)
300			}
301			h, ok := l.Handoffs[r.Handoff]
302			if !ok {
303				return fmt.Errorf("%w: 退回请求号 %q 引用了不存在的原交接 %q", ErrCorrupt, req, r.Handoff)
304			}
305			if h.ReturnedBy != req || r.From != h.To || r.To != h.From || !sameSet(r.Parcels, h.Parcels) {
306				return fmt.Errorf("%w: 退回请求号 %q 与原交接 %q 的记录不一致", ErrCorrupt, req, r.Handoff)
307			}
308			for _, id := range r.Parcels {
309				if _, ok := l.Parcels[id]; !ok {
310					return fmt.Errorf("%w: 退回请求号 %q 引用了不存在的包裹 %q", ErrCorrupt, req, id)
311				}
312			}
313		}
314		for id, b := range l.Batches {
315			if b == nil || id != b.Batch || b.Station == "" || b.Courier == "" || len(b.Parcels) == 0 || b.Time.IsZero() {
316				return fmt.Errorf("%w: 批次号 %q 的出站结果不完整", ErrCorrupt, id)
317			}
318			seen := make(map[string]bool, len(b.Parcels))
319			for _, pid := range b.Parcels {
320				if seen[pid] {
321					return fmt.Errorf("%w: 批次 %q 的成员 %q 重复", ErrCorrupt, id, pid)
322				}
323				seen[pid] = true
324				if _, ok := l.Parcels[pid]; !ok {
325					return fmt.Errorf("%w: 批次 %q 引用了不存在的包裹 %q", ErrCorrupt, id, pid)
326				}
327			}
328			for pid, e := range b.Receipts {
329				if e == nil || !seen[pid] || e.Request == "" || e.Time.IsZero() ||
330					(e.Result != resultSigned && e.Result != resultFailed) ||
331					(e.Result == resultFailed && e.Reason == "") || (e.Result == resultSigned && e.Reason != "") {
332					return fmt.Errorf("%w: 批次 %q 中包裹 %q 的回执记录不完整", ErrCorrupt, id, pid)
333				}
334				rc, ok := l.Receipts[e.Request]
335				if !ok || rc.Batch != id || rc.Parcel != pid {
336					return fmt.Errorf("%w: 批次 %q 中包裹 %q 的回执请求号 %q 无法对应", ErrCorrupt, id, pid, e.Request)
337				}
338			}
339		}
340		for req, rc := range l.Receipts {
341			if rc == nil || req != rc.Request || rc.Batch == "" || rc.Parcel == "" || rc.Time.IsZero() ||
342				(rc.Result != resultSigned && rc.Result != resultFailed) ||
343				(rc.Result == resultFailed && rc.Reason == "") || (rc.Result == resultSigned && rc.Reason != "") {
344				return fmt.Errorf("%w: 回执请求号 %q 的回执结果不完整", ErrCorrupt, req)
345			}
346			b, ok := l.Batches[rc.Batch]
347			if !ok {
348				return fmt.Errorf("%w: 回执请求号 %q 引用了不存在的批次 %q", ErrCorrupt, req, rc.Batch)
349			}
350			e, ok := b.Receipts[rc.Parcel]
351			if !ok || e.Request != req || e.Result != rc.Result || e.Reason != rc.Reason || !e.Time.Equal(rc.Time) {
352				return fmt.Errorf("%w: 回执请求号 %q 与批次 %q 的回执记录不一致", ErrCorrupt, req, rc.Batch)
353			}
354		}
355		// 冻结/解除冻结：先遍历轨迹核对冻结与解除必须成对出现、顺序正确，
356		// 再核对两张结果表与包裹当前状态的对应关系。
357		openIncident := make(map[string]string) // 包裹 -> 当前未解除的异常单号（由轨迹推导）
358		for id, p := range l.Parcels {
359			var open string
360			for i, e := range p.Trail {
361				switch e.Op {
362				case "冻结":
363					if open != "" {
364						return fmt.Errorf("%w: 包裹 %q 第 %d 条冻结时异常单 %q 尚未解除，一件包裹同时只能有一张未解除异常单",
365							ErrCorrupt, id, i+1, open)
366					}
367					open = e.Incident
368				case "解除冻结":
369					if open != e.Incident {
370						return fmt.Errorf("%w: 包裹 %q 第 %d 条解除的异常单 %q 与当前冻结 %q 不匹配",
371							ErrCorrupt, id, i+1, e.Incident, open)
372					}
373					open = ""
374				}
375			}
376			if p.Status == statusFrozen && open == "" {
377				return fmt.Errorf("%w: 包裹 %q 当前为异常冻结，但轨迹中没有未解除的冻结记录", ErrCorrupt, id)
378			}
379			if p.Status != statusFrozen && open != "" {
380				return fmt.Errorf("%w: 包裹 %q 当前状态为 %q，但异常单 %q 尚未解除", ErrCorrupt, id, p.Status, open)
381			}
382			if open != "" {
383				openIncident[id] = open
384			}
385		}
386		for no, f := range l.Freezes {
387			if f == nil || no != f.Incident || f.Parcel == "" || f.Station == "" || f.Reason == "" || f.Time.IsZero() {
388				return fmt.Errorf("%w: 异常单号 %q 的冻结结果不完整", ErrCorrupt, no)
389			}
390			p, ok := l.Parcels[f.Parcel]
391			if !ok {
392				return fmt.Errorf("%w: 异常单 %q 引用了不存在的包裹 %q", ErrCorrupt, no, f.Parcel)
393			}
394			if f.ReleasedBy == "" && p.Station != f.Station {
395				return fmt.Errorf("%w: 异常单 %q 记录的站点 %q 与包裹 %q 当前站点 %q 不一致",
396					ErrCorrupt, no, f.Station, f.Parcel, p.Station)
397			}
398			if f.ReleasedBy != "" {
399				u, ok := l.Unfreezes[f.ReleasedBy]
400				if !ok || u.Incident != no || u.Parcel != f.Parcel {
401					return fmt.Errorf("%w: 异常单 %q 标记的解除请求号 %q 无法对应", ErrCorrupt, no, f.ReleasedBy)
402				}
403			}
404		}
405		activeByParcel := make(map[string]string)
406		for req, u := range l.Unfreezes {
407			if u == nil || req != u.Request || u.Incident == "" || u.Parcel == "" || u.Note == "" || u.Time.IsZero() {
408				return fmt.Errorf("%w: 解除请求号 %q 的解除结果不完整", ErrCorrupt, req)
409			}
410			f, ok := l.Freezes[u.Incident]
411			if !ok {
412				return fmt.Errorf("%w: 解除请求号 %q 引用了不存在的异常单 %q", ErrCorrupt, req, u.Incident)
413			}
414			if f.Parcel != u.Parcel {
415				return fmt.Errorf("%w: 解除请求号 %q 与异常单 %q 对应的包裹不一致", ErrCorrupt, req, u.Incident)
416			}
417			if f.ReleasedBy != req {
418				return fmt.Errorf("%w: 解除请求号 %q 与异常单 %q 的解除标记不一致", ErrCorrupt, req, u.Incident)
419			}
420		}
421		for no, f := range l.Freezes {
422			if f.ReleasedBy != "" {
423				continue
424			}
425			if other, dup := activeByParcel[f.Parcel]; dup {
426				return fmt.Errorf("%w: 包裹 %q 同时存在两张未解除异常单 %q 与 %q", ErrCorrupt, f.Parcel, other, no)
427			}
428			activeByParcel[f.Parcel] = no
429			if openIncident[f.Parcel] != no {
430				return fmt.Errorf("%w: 包裹 %q 当前冻结对应的异常单应为 %q，与未解除异常单 %q 不匹配",
431					ErrCorrupt, f.Parcel, openIncident[f.Parcel], no)
432			}
433			if p := l.Parcels[f.Parcel]; p.Status != statusFrozen {
434				return fmt.Errorf("%w: 异常单 %q 未解除，但包裹 %q 当前状态为 %q", ErrCorrupt, no, f.Parcel, p.Status)
435			}
436		}
437		return nil
438	}
