440	// Register 执行单件收件登记并将结果整体落盘。
441	func (s *Store) Register(id, station string, now time.Time) (*Parcel, error) {
442		if _, ok := s.data.Parcels[id]; ok {
443			return nil, fmt.Errorf("包裹编号 %q 已登记，不能重复登记", id)
444		}
445		p := &Parcel{
446			ID:         id,
447			Station:    station,
448			Status:     statusInStation,
449			Registered: now,
450			Trail: []Event{{
451				Op:      "收件",
452				Station: station,
453				Time:    now,
454			}},
455		}
456		s.data.Parcels[id] = p
457		if err := s.save(); err != nil {
458			delete(s.data.Parcels, id) // 落盘失败：回滚内存变更，保留原有有效数据
459			return nil, err
460		}
461		return p, nil
462	}
