422	// receiptFileRecord 是回执整批导入文件中的单条记录（JSON）。
423	type receiptFileRecord struct {
424		Request string `json:"request"`
425		Batch   string `json:"batch"`
426		Parcel  string `json:"parcel"`
427		Result  string `json:"result"`
428		Reason  string `json:"reason"`
429	}
430	
431	// loadReceiptImportFile 读取并解析回执整批导入文件。文件为有序且非空的
432	// JSON 数组，元素为 request/batch/parcel/result/reason 字段的对象；
433	// 文件只读，绝不改写。任一记录清洗后不合法或请求号在文件内重复，
434	// 都返回带记录位置的错误，整份不予导入。
435	func loadReceiptImportFile(path string) ([]ReceiptImportRecord, error) {
436		raw, err := os.ReadFile(path)
437		if err != nil {
438			return nil, fmt.Errorf("读取回执导入文件失败: %w", err)
439		}
440		dec := json.NewDecoder(bytes.NewReader(raw))
441		dec.DisallowUnknownFields()
442		var records []receiptFileRecord
443		if err := dec.Decode(&records); err != nil {
444			return nil, fmt.Errorf("解析回执导入文件失败: %w", err)
445		}
446		var extra any
447		if err := dec.Decode(&extra); err != io.EOF {
448			return nil, fmt.Errorf("解析回执导入文件失败: 回执列表之后存在多余内容")
449		}
450		if len(records) == 0 {
451			return nil, fmt.Errorf("回执导入文件必须是有序且非空的回执列表")
452		}
453	
454		clean := make([]ReceiptImportRecord, 0, len(records))
455		seen := make(map[string]bool, len(records))
456		for i, rawRec := range records {
457			rec, err := cleanReceiptImportRecord(rawRec)
458			if err != nil {
459				return nil, fmt.Errorf("第 %d 条记录: %w", i+1, err)
460			}
461			if seen[rec.Request] {
462				return nil, fmt.Errorf("第 %d 条记录: 回执请求号 %q 在文件内重复", i+1, rec.Request)
463			}
464			seen[rec.Request] = true
465			clean = append(clean, rec)
466		}
467		return clean, nil
468	}
469	
470	// cleanReceiptImportRecord 清洗并校验一条导入记录：各标识去除两端空白后不可为空；
471	// 结果为失败时必须给出清理后非空的原因，签收时不可带原因。
472	func cleanReceiptImportRecord(raw receiptFileRecord) (ReceiptImportRecord, error) {
473		var rec ReceiptImportRecord
474		var err error
475		if rec.Request, err = cleanID("回执请求号", raw.Request); err != nil {
476			return rec, err
477		}
478		if rec.Batch, err = cleanID("批次号", raw.Batch); err != nil {
479			return rec, err
480		}
481		if rec.Parcel, err = cleanID("包裹编号", raw.Parcel); err != nil {
482			return rec, err
483		}
484		if rec.Result, err = cleanID("回执结果", raw.Result); err != nil {
485			return rec, err
486		}
487		if rec.Result != resultSigned && rec.Result != resultFailed {
488			return rec, fmt.Errorf("回执结果只能是 %q 或 %q，得到 %q", resultSigned, resultFailed, rec.Result)
489		}
490		rec.Reason = strings.TrimSpace(raw.Reason)
491		if rec.Result == resultFailed && rec.Reason == "" {
492			return rec, fmt.Errorf("结果为失败时原因不可为空或仅含空白")
493		}
494		if rec.Result == resultSigned && rec.Reason != "" {
495			return rec, fmt.Errorf("结果为签收时不可带原因")
496		}
497		return rec, nil
498	}
