559	func TestReturnPersistenceAcrossRestart(t *testing.T) {
560		_, path := openTempStore(t)
561		s1, err := Open(path)
562		if err != nil {
563			t.Fatal(err)
564		}
565		mustRegister(t, s1, "P001", "站点A", tClock(2026, 10, 5, 9, 0))
566		mustHandoff(t, s1, "R1", "站点A", "站点B", []string{"P001"}, tClock(2026, 10, 5, 10, 0))
567		if _, _, err := s1.Return("RT1", "R1", "错发", tClock(2026, 10, 5, 11, 0)); err != nil {
568			t.Fatal(err)
569		}
570	
571		s2, err := Open(path)
572		if err != nil {
573			t.Fatalf("重新打开失败: %v", err)
574		}
575		p, _ := s2.Query("P001")
576		if p.Station != "站点A" || len(p.Trail) != 3 || p.Trail[2].Op != "退回" || p.Trail[2].RefRequest != "R1" {
577			t.Fatalf("重启后退回轨迹不符: %+v", p)
578		}
579		// 重启后退回重放仍成立。
580		if _, replayed, err := s2.Return("RT1", "R1", "错发", tClock(2026, 10, 5, 12, 0)); err != nil || !replayed {
581			t.Fatalf("重启后退回重放失败: %v replayed=%v", err, replayed)
582		}
583		// 重启后同一原交接仍不能再次退回。
584		if _, _, err := s2.Return("RT2", "R1", "再来", tClock(2026, 10, 5, 12, 30)); err == nil {
585			t.Fatal("重启后已退回的原交接仍须拒绝再次退回")
586		}
587		// 重启后原交接重放仍成立。
588		if _, replayedH, err := s2.Handoff("R1", "站点A", "站点B", []string{"P001"}, tClock(2026, 10, 5, 13, 0)); err != nil || !replayedH {
589			t.Fatalf("重启后原交接重放失败: %v replayed=%v", err, replayedH)
590		}
591	}
