593	func TestCorruptReturnDataRejected(t *testing.T) {
594		dir := t.TempDir()
595		path := filepath.Join(dir, "ledger.json")
596	
597		parcel := `"id":"P1","station":"A","status":"在站","registered":"2026-10-05T09:00:00Z"`
598		goodTrail := `"op":"收件","station":"A","time":"2026-10-05T09:00:00Z"`
599		cases := map[string]string{
600			"轨迹缺少操作": `{"version":1,"parcels":{"P1":{` + parcel + `,"trail":[{"station":"A","time":"2026-10-05T09:00:00Z"}]}},"handoffs":{},"returns":{}}`,
601			"轨迹缺少站点": `{"version":1,"parcels":{"P1":{` + parcel + `,"trail":[{"op":"收件","time":"2026-10-05T09:00:00Z"}]}},"handoffs":{},"returns":{}}`,
602			"轨迹缺少时间": `{"version":1,"parcels":{"P1":{` + parcel + `,"trail":[{"op":"收件","station":"A"}]}},"handoffs":{},"returns":{}}`,
603			"退回引用不存在的原交接": `{"version":1,"parcels":{"P1":{` + parcel + `,"trail":[{` + goodTrail + `}]}},"handoffs":{},` +
604				`"returns":{"RT1":{"request":"RT1","handoff":"NOPE","from":"B","to":"A","reason":"x","parcels":["P1"],"time":"2026-10-05T10:00:00Z"}}}`,
605			"退回轨迹引用不存在的原交接": `{"version":1,"parcels":{"P1":{` + parcel + `,"trail":[{` + goodTrail + `},` +
606				`{"op":"退回","station":"A","from":"B","time":"2026-10-05T10:00:00Z","request":"RT1","refRequest":"NOPE","reason":"x"}]}},"handoffs":{},"returns":{}}`,
607		}
608		for name, content := range cases {
609			t.Run(name, func(t *testing.T) {
610				if err := os.WriteFile(path, []byte(content), 0o644); err != nil {
611					t.Fatal(err)
612				}
613				if _, err := Open(path); err == nil {
614					t.Fatal("损坏文件必须被拒绝打开")
615				} else if !errors.Is(err, ErrCorrupt) {
616					t.Fatalf("应返回 ErrCorrupt，得到 %v", err)
617				}
618				got, _ := os.ReadFile(path)
619				if string(got) != content {
620					t.Fatal("损坏文件不得被覆盖")
621				}
622			})
623		}
624	}
